<FILEPATH>
src/app.controller.ts
</FILEPATH>
<CODE>
import { Controller, Post, Body, Get, Res, HttpException, HttpStatus } from '@nestjs/common';
import { AppService } from './app.service';
import { Response } from 'express';

@Controller()
export class AppController {
  constructor(private readonly appService: AppService) {}

  @Post('log')
  logMessage(@Body() body: { message: string }): string {
    if (!body.message || typeof body.message !== 'string') {
      throw new HttpException('Invalid message', HttpStatus.BAD_REQUEST);
    }
    this.appService.logMessage(body.message);
    return 'Log message successful';
  }

  @Get('logs')
  getLogs(@Res() res: Response): void {
    const logs = this.appService.getLogs();
    res.type('text/plain').send(logs);
  }
}
</CODE>

<FILEPATH>
src/app.service.ts
</FILEPATH>
<CODE>
import { Injectable } from '@nestjs/common';
import * as fs from 'fs';
import * as path from 'path';

@Injectable()
export class AppService {
  private logFilePath = path.join(__dirname, '..', 'logs.txt');

  logMessage(message: string): void {
    try {
      fs.appendFileSync(this.logFilePath, message + '\n', 'utf8');
    } catch (error) {
      console.error('Error writing to log file:', error);
    }
  }

  getLogs(): string {
    try {
      if (fs.existsSync(this.logFilePath)) {
        return fs.readFileSync(this.logFilePath, 'utf8');
      }
      return 'No logs found';
    } catch (error) {
      console.error('Error reading log file:', error);
      return 'Error retrieving logs';
    }
  }
}
</CODE>

<FILEPATH>
src/app.module.ts
</FILEPATH>
<CODE>
import { Module } from '@nestjs/common';
import { AppController } from './app.controller';
import { AppService } from './app.service';

@Module({
  imports: [],
  controllers: [AppController],
  providers: [AppService],
})
export class AppModule {}
</CODE>

<FILEPATH>
src/main.ts
</FILEPATH>
<CODE>
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  app.enableCors(); // Enable CORS if needed
  await app.listen(5000);
}
bootstrap();
</CODE>

